mkdir -p tests/tmpscratch && cat > tests/tmpscratch/bulk.test.ts <<'EOF'
import { afterAll, beforeAll, expect, it, vi } from "vitest";
vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
import { subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as issueService from "@/server/services/issue-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
let cleanup: () => void; let t: Tenant; let other: Tenant;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); t = await createTenant("bulk"); other = await createTenant("bulk2"); });
afterAll(() => cleanup());
it("works", async () => {
  const m = t.actors.member; const o = t.actors.owner; const v = t.actors.viewer;
  const a = await issueService.createIssue(m, issueInput(t.org.id, t.project.id, { title: "aaa" }));
  const b = await issueService.createIssue(m, issueInput(t.org.id, t.project.id, { title: "bbb" }));
  const c = await issueService.createIssue(o, issueInput(t.org.id, t.project.id, { title: "ccc", assigneeId: v.userId }));
  const d = await issueService.createIssue(o, issueInput(t.org.id, t.project.id, { title: "ddd" }));
  const x = await issueService.createIssue(other.actors.owner, issueInput(other.org.id, other.project.id, { title: "xxx" }));
  await issueService.archiveIssue(o, t.org.id, d.id);
  const dBefore = (await issueRepo.findIssueById(t.org.id, d.id))!.archivedAt;
  const events: string[] = [];
  const off = subscribe("issue.archived", (p) => { events.push(p.issueId); });
  await expect(issueService.bulkArchiveIssues(o, { orgId: other.org.id, issueIds: [a.id] })).rejects.toBeInstanceOf(TenantScopeError);
  await expect(issueService.bulkArchiveIssues(v, { orgId: t.org.id, issueIds: [c.id, a.id] })).rejects.toBeInstanceOf(PermissionDeniedError);
  expect(events).toEqual([]);
  expect((await issueRepo.findIssueById(t.org.id, c.id))!.archivedAt).toBeNull();
  const r = await issueService.bulkArchiveIssues(v, { orgId: t.org.id, issueIds: [d.id, c.id, x.id, c.id] });
  expect(r).toEqual({ archived: [c.id], skipped: [d.id, x.id] });
  const r2 = await issueService.bulkArchiveIssues(m, { orgId: t.org.id, issueIds: [b.id, a.id, b.id, "01ARZ3NDEKTSV4RRFFQ69G5FAV" as never] });
  expect(r2.archived).toEqual([b.id, a.id]);
  expect(events).toEqual([c.id, b.id, a.id]);
  expect((await issueRepo.findIssueById(t.org.id, d.id))!.archivedAt).toBe(dBefore);
  expect((await issueRepo.findIssuesByIds(t.org.id, [])).length).toBe(0);
  expect((await issueRepo.findIssuesByIds(t.org.id, [a.id, x.id, d.id])).length).toBe(2);
  off();
});
EOF
